# Surah An-Nisa (chapter 4) — part 2: ayat 11-14 & 15-20 scope: ayat 11-20 (IDs 504-513)
SURAH = 4

ENTRIES = {
504: (
"اللہ تمہیں تمہاری اولاد کے بارے میں حکم دیتا ہے — ایک بیٹے کے لیے دو بیٹیوں کے برابر حصہ ہے — پھر اگر صرف بیٹیاں ہی ہوں اور دو سے زیادہ ہوں تو ان کے لیے اس (مال) کا دو تہائی حصہ ہے جو (میت) چھوڑے — اور اگر ایک ہی بیٹی ہو تو اس کے لیے آدھا ہے — اور (میت کے) والدین — ان میں سے ہر ایک کے لیے — اس کا چھٹا حصہ ہے جو اس نے چھوڑا اگر اس کی اولاد ہو — پھر اگر اس کی کوئی اولاد نہ ہو اور اس کے وارث صرف والدین ہوں تو اس کی ماں کے لیے ایک تہائی ہے — پھر اگر اس کے بھائی بہن ہوں تو اس کی ماں کے لیے چھٹا حصہ ہے — یہ (سب) اس وصیت کے بعد ہوگا جو وہ (میت) کرے یا قرض کے بعد — تمہارے باپ اور تمہارے بیٹے — تم نہیں جانتے کہ ان میں سے کون تمہیں نفع دینے میں زیادہ قریب ہے — (یہ تقسیم) اللہ کی طرف سے فرض ہے — بے شک اللہ جاننے والا، حکمت والا ہے۔",
"""۱۔ میراث کے تفصیلی احکام — اللہ کا عین مقرر کیا ہوا نظام۔
۲۔ ’’يُوصِيكُمُ اللّٰہُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ‘‘ — اللہ تمہیں تمہاری اولاد کے بارے میں حکم دیتا ہے — ایک بیٹے کے لیے دو بیٹیوں کے برابر حصہ ہے — یعنی لڑکے کو لڑکی سے دوگنا حصہ — لڑکے پر کفالت اور نفقہ کی ذمہ داری کی وجہ سے۔
۳۔ ’’فَإِن كُنَّ نِسَاءً فَوْقَ اثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ‘‘ — پھر اگر صرف بیٹیاں ہی ہوں اور دو سے زیادہ ہوں تو ان کے لیے اس (مال) کا دو تہائی حصہ ہے جو (میت) چھوڑے۔
۴۔ ’’وَإِن كَانَتْ وَاحِدَۃً فَلَهَا النِّصْفُ‘‘ — اور اگر ایک ہی بیٹی ہو تو اس کے لیے آدھا ہے۔
۵۔ ’’وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِّنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُ وَلَدٌ‘‘ — اور (میت کے) والدین — ان میں سے ہر ایک کے لیے — اس کا چھٹا حصہ ہے جو اس نے چھوڑا اگر اس کی اولاد ہو۔
۶۔ ’’فَإِن لَّمْ يَكُن لَّهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ‘‘ — پھر اگر اس کی کوئی اولاد نہ ہو اور اس کے وارث صرف والدین ہوں تو اس کی ماں کے لیے ایک تہائی ہے۔
۷۔ ’’فَإِن كَانَ لَهُ إِخْوَۃٌ فَلِأُمِّهِ السُّدُسُ‘‘ — پھر اگر اس کے بھائی بہن ہوں تو اس کی ماں کے لیے چھٹا حصہ ہے۔
۸۔ ’’مِن بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ‘‘ — یہ (سب) اس وصیت کے بعد ہوگا جو وہ (میت) کرے یا قرض کے بعد — یعنی میراث سے پہلے وصیت اور قرض ادا کریں گے۔
۹۔ ’’آبَاؤُكُمْ وَأَبْنَاؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا‘‘ — تمہارے باپ اور تمہارے بیٹے — تم نہیں جانتے کہ ان میں سے کون تمہیں نفع دینے میں زیادہ قریب ہے — یعنی اللہ کا مقررہ نظام انسانی علم سے بلند ہے۔
۱۰۔ ’’فَرِيضَۃً مِّنَ اللّٰہِ إِنَّ اللّٰہَ كَانَ عَلِيمًا حَكِيمًا‘‘ — (یہ تقسیم) اللہ کی طرف سے فرض ہے — بے شک اللہ جاننے والا، حکمت والا ہے۔
۱۱۔ عملی سبق: اللہ کے مقرر کردہ حصوں میں اپنی مرضی سے تبدیلی نہ کرو؛ وصیت اور قرض پہلے ادا کرو۔"""
),
505: (
"اور تمہارے لیے تمہاری بیویوں کے چھوڑے ہوئے مال کا آدھا ہے اگر ان کی اولاد نہ ہو — پھر اگر ان کی اولاد ہو تو تمہارے لیے اس کا چوتھا حصہ ہے جو انہوں نے چھوڑا — یہ اس وصیت کے بعد ہوگا جو وہ کریں یا قرض کے بعد — اور ان کے لیے تمہارا چوتھا حصہ ہے جو تم چھوڑتے ہو اگر تمہاری اولاد نہ ہو — پھر اگر تمہاری اولاد ہو تو ان کے لیے تمہارے مال کا آٹھواں حصہ ہے — یہ اس وصیت کے بعد ہوگا جو تم کرو یا قرض کے بعد — اور اگر کوئی مرد یا عورت ایسا ہو جس کا کلالہ سے وارث (پورا) ہو — اور اس کے لیے ایک بھائی ہو یا ایک بہن — تو ان میں سے ہر ایک کے لیے چھٹا حصہ ہے — پھر اگر ایک سے زیادہ ہوں تو سب ایک تہائی (ثلث) میں شریک ہیں — یہ اس وصیت کے بعد ہوگا جو وصیت کی جائے یا قرض کے بعد — (ایسی) وصیت جو نقصان نہ پہنچائے (وارثوں کو) — یہ اللہ کی طرف سے وصیت ہے — اور اللہ جاننے والا، تحمل والا ہے۔",
"""۱۔ شوہر، بیوی اور کلالہ (بہن بھائی) کی وراثت۔
۲۔ ’’وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَاجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ‘‘ — اور تمہارے لیے تمہاری بیویوں کے چھوڑے ہوئے مال کا آدھا ہے اگر ان کی اولاد نہ ہو — یعنی شوہر کو بیوی کے مال کا آدھا حصہ۔
۳۔ ’’فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ الرُّبُعُ مِمَّا تَرَكْنَ‘‘ — پھر اگر ان کی اولاد ہو تو تمہارے لیے اس کا چوتھا حصہ ہے جو انہوں نے چھوڑا۔
۴۔ ’’وَلَهُنَّ الرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ‘‘ — اور ان کے لیے تمہارا چوتھا حصہ ہے جو تم چھوڑتے ہو اگر تمہاری اولاد نہ ہو — بیوی کو شوہر کے مال کا ۱/۴۔
۵۔ ’’فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ الثُّمُنُ مِمَّا تَرَكْتُمْ‘‘ — پھر اگر تمہاری اولاد ہو تو ان کے لیے تمہارے مال کا آٹھواں حصہ ہے۔
۶۔ ’’وَإِن كَانَ رَجُلٌ يُورَثُ كَلَالَۃً أَوِ امْرَأَۃٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِّنْهُمَا السُّدُسُ‘‘ — اور اگر کوئی مرد یا عورت ایسا ہو جس کا کلالہ سے وارث (پورا) ہو — اور اس کے لیے ایک بھائی ہو یا ایک بہن — تو ان میں سے ہر ایک کے لیے چھٹا حصہ ہے — کلالہ: جس کی اولاد اور والدین نہ ہوں۔
۷۔ ’’فَإِن كَانُوا أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ‘‘ — پھر اگر ایک سے زیادہ ہوں تو سب ایک تہائی (ثلث) میں شریک ہیں۔
۸۔ ’’مِن بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَا أَوْ دَيْنٍ غَيْرَ مُضَارٍّ‘‘ — یہ اس وصیت کے بعد ہوگا جو وصیت کی جائے یا قرض کے بعد — (ایسی) وصیت جو نقصان نہ پہنچائے (وارثوں کو) — یعنی وصیت سے وارثوں کو نقصان نہ پہنچایا جائے — یہ اللہ کی وصیت ہے۔
۹۔ ’’وَصِيَّۃً مِّنَ اللّٰہِ وَاللّٰہُ عَلِيمٌ حَلِيمٌ‘‘ — یہ اللہ کی طرف سے وصیت ہے — اور اللہ جاننے والا، تحمل والا ہے۔
۱۰۔ عملی سبق: میراث کی تقسیم میں اللہ کے حصوں کی پوری پیروی کرو؛ وصیت میں وارثوں کو نقصان نہ پہنچاؤ۔"""
),
506: (
"یہ اللہ کی حدود (مقرر کردہ حدیں) ہیں — اور جو اللہ اور اس کے رسول کی اطاعت کرے — وہ اسے ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں — وہ ان میں ہمیشہ رہیں گے — اور یہ بہت بڑی کامیابی ہے۔",
"""۱۔ یہ سب احکام اللہ کی مقرر کردہ حدود ہیں۔
۲۔ ’’تِلْكَ حُدُودُ اللّٰہِ‘‘ — یہ اللہ کی حدود (مقرر کردہ حدیں) ہیں۔
۳۔ ’’وَمَن يُطِعِ اللّٰہَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا‘‘ — اور جو اللہ اور اس کے رسول کی اطاعت کرے — وہ اسے ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں — وہ ان میں ہمیشہ رہیں گے۔
۴۔ ’’وَذَٰلِكَ الْفَوْزُ الْعَظِيمُ‘‘ — اور یہ بہت بڑی کامیابی ہے۔
۵۔ عملی سبق: اللہ کے احکام کی پوری اطاعت کرو — یہی اصل کامیابی ہے۔"""
),
507: (
"اور جو اللہ اور اس کے رسول کی نافرمانی کرے اور اس کی حدود سے تجاوز کرے — وہ اسے آگ میں داخل کرے گا جس میں وہ ہمیشہ رہے گا — اور اس کے لیے رسوا کن عذاب ہے۔",
"""۱۔ اللہ کی حدود سے تجاوز کا انجام — جہنم میں ہمیشگی۔
۲۔ ’’وَمَن يَعْصِ اللّٰہَ وَرَسُولَهُ وَيَتَعَدَّ حُدُودَهُ يُدْخِلْهُ نَارًا خَالِدًا فِيهَا‘‘ — اور جو اللہ اور اس کے رسول کی نافرمانی کرے اور اس کی حدود سے تجاوز کرے — وہ اسے آگ میں داخل کرے گا جس میں وہ ہمیشہ رہے گا — یعنی نافرمانی اور تعدی دونوں جہنم کا سبب ہیں۔
۳۔ ’’وَلَهُ عَذَابٌ مُّهِينٌ‘‘ — اور اس کے لیے رسوا کن عذاب ہے۔
۴۔ عملی سبق: اللہ کی حدود میں رہو؛ نافرمانی اور تجاوز سے بچو۔"""
),
508: (
"اور تمہاری عورتوں میں سے جو بے حیائی کا ارتکاب کرتی ہوں — ان پر اپنوں میں سے چار گواہ مقرر کرو — پھر اگر وہ گواہی دیں تو انہیں گھروں میں روکے رکھو — یہاں تک کہ موت انہیں اٹھا لے یا اللہ ان کے لیے (کوئی) راستہ بنا دے۔",
"""۱۔ زنا کے ثبوت کے سخت تقاضے — چار گواہ۔
۲۔ ’’وَاللَّاتِي يَأْتِينَ الْفَاحِشَۃَ مِن نِّسَائِكُمْ فَاسْتَشْهِدُوا عَلَيْهِنَّ أَرْبَعَۃً مِّنكُمْ‘‘ — اور تمہاری عورتوں میں سے جو بے حیائی کا ارتکاب کرتی ہوں — ان پر اپنوں میں سے چار گواہ مقرر کرو — یعنی زنا کے ثبوت کے لیے چار عادل گواہ ضروری ہیں۔
۳۔ ’’فَإِن شَهِدُوا فَأَمْسِكُوهُنَّ فِي الْبُيُوتِ حَتَّىٰ يَتَوَفَّاهُنَّ الْمَوْتُ أَوْ يَجْعَلَ اللّٰہُ لَهُنَّ سَبِيلًا‘‘ — پھر اگر وہ گواہی دیں تو انہیں گھروں میں روکے رکھو — یہاں تک کہ موت انہیں اٹھا لے یا اللہ ان کے لیے (کوئی) راستہ بنا دے — یعنی سزا کے منتظر رہنا — بعد میں سورۂ نور (۲۴:۲) نے سزا کے احکام بیان فرمائے۔
۴۔ عملی سبق: زنا کے الزام میں احتیاط لازم ہے؛ بغیر چار گواہوں کے کسی پر الزام نہ لگاؤ۔"""
),
509: (
"اور تم میں سے جو دو (افراد) اس (بے حیائی) کا ارتکاب کریں تو انہیں (سزا دیکر) تکلیف دو — پھر اگر وہ توبہ کریں اور اصلاح کریں تو ان سے دستبردار ہو جاؤ — بے شک اللہ توبہ قبول کرنے والا، مہربان ہے۔",
"""۱۔ اللہ نے دونوں جنسوں کو برابر ذمہ دار ٹھہرایا ہے — اور توبہ کا دروازہ بھی کھلا رکھا۔
۲۔ ’’وَاللَّذَانِ يَأْتِيَانِهَا مِنكُمْ فَآذُوهُمَا‘‘ — اور تم میں سے جو دو (افراد) اس (بے حیائی) کا ارتکاب کریں تو انہیں (سزا دیکر) تکلیف دو۔
۳۔ ’’فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا عَنْهُمَا‘‘ — پھر اگر وہ توبہ کریں اور اصلاح کریں تو ان سے دستبردار ہو جاؤ — یعنی توبہ کے بعد انہیں معاف کر دو۔
۴۔ ’’إِنَّ اللّٰہَ كَانَ تَوَّابًا رَّحِيمًا‘‘ — بے شک اللہ توبہ قبول کرنے والا، مہربان ہے۔
۵۔ عملی سبق: توبہ اور اصلاح کے بعد کسی کو رسوا نہ کرو؛ اللہ بھی معاف کرتا ہے۔"""
),
510: (
"بے شک توبہ (قبول کرنا) اللہ پر صرف ان لوگوں کی ہے جو بے وقوفی کی وجہ سے (گناہ) کرتے ہیں پھر جلد ہی توبہ کر لیتے ہیں — تو ایسے لوگوں کی اللہ توبہ قبول فرماتا ہے — اور اللہ جاننے والا، حکمت والا ہے۔",
"""۱۔ توبہ کی قبولیت — فوراً اور سچی توبہ۔
۲۔ ’’إِنَّمَا التَّوْبَۃُ عَلَى اللّٰہِ لِلَّذِينَ يَعْمَلُونَ السُّوءَ بِجَهَالَۃٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ‘‘ — بے شک توبہ (قبول کرنا) اللہ پر صرف ان لوگوں کی ہے جو بے وقوفی کی وجہ سے (گناہ) کرتے ہیں پھر جلد ہی توبہ کر لیتے ہیں — یعنی گناہ کے فوراً بعد سچی توبہ لازماً قبول ہوتی ہے۔
۳۔ ’’فَأُولَٰئِكَ يَتُوبُ اللّٰہُ عَلَيْهِمْ وَكَانَ اللّٰہُ عَلِيمًا حَكِيمًا‘‘ — تو ایسے لوگوں کی اللہ توبہ قبول فرماتا ہے — اور اللہ جاننے والا، حکمت والا ہے۔
۴۔ عملی سبق: گناہ ہوتے ہی فوراً توبہ کرو؛ دیر نہ کرو — اللہ فوراً معاف فرما دیتا ہے۔"""
),
511: (
"اور توبہ ان لوگوں کے لیے نہیں ہے جو برائیوں میں لگے رہیں — یہاں تک کہ جب ان میں سے کسی کو موت آجائے تو وہ کہے: میں نے ابھی توبہ کی — اور نہ ان کے لیے جو کفر کی حالت میں مر جائیں — ان کے لیے ہم نے دردناک عذاب تیار کیا ہے۔",
"""۱۔ موت کے وقت کی توبہ ناقابل قبول۔
۲۔ ’’وَلَيْسَتِ التَّوْبَۃُ لِلَّذِينَ يَعْمَلُونَ السَّيِّئَاتِ حَتَّىٰ إِذَا حَضَرَ أَحَدَهُمُ الْمَوْتُ قَالَ إِنِّي تُبْتُ الْآنَ‘‘ — اور توبہ ان لوگوں کے لیے نہیں ہے جو برائیوں میں لگے رہیں — یہاں تک کہ جب ان میں سے کسی کو موت آجائے تو وہ کہے: میں نے ابھی توبہ کی — یعنی موت آتے ہی کی ہوئی توبہ معتبر نہیں۔
۳۔ ’’وَلَا الَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ‘‘ — اور نہ ان کے لیے جو کفر کی حالت میں مر جائیں۔
۴۔ ’’أُولَٰئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا‘‘ — ان کے لیے ہم نے دردناک عذاب تیار کیا ہے۔
۵۔ عملی سبق: توبہ ہمیشہ ابھی کرو؛ موت آنے کا انتظار مت کرو۔"""
),
512: (
"اے ایمان والو! تمہارے لیے جائز نہیں کہ تم عورتوں کو زبردستی وراثت میں لے لو — اور نہ انہیں روک رکھنے (سے) کہ تم نے جو انہیں دیا ہے اس میں سے کچھ لے لو — سوائے اس کے کہ وہ کھلی بے حیائی کا ارتکاب کریں — اور ان کے ساتھ معروف طریقے سے زندگی گزارو — پھر اگر تم انہیں ناپسند کرو تو شاید کہ تم کسی چیز کو ناپسند کرو اور اللہ اس میں بہت زیادہ بھلائی رکھ دے۔",
"""۱۔ عورتوں کے حقوق — وراثت، مہر اور حسنِ معاشرت۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَحِلُّ لَكُمْ أَن تَرِثُوا النِّسَاءَ كَرْهًا‘‘ — اے ایمان والو! تمہارے لیے جائز نہیں کہ تم عورتوں کو زبردستی وراثت میں لے لو — یعنی جاہلیت کی طرح میت کی بیوی کو وراثت میں لینا حرام ہے۔
۳۔ ’’وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا بِبَعْضِ مَا آتَيْتُمُوهُنَّ إِلَّا أَن يَأْتِينَ بِفَاحِشَۃٍ مُّبَيِّنَۃٍ‘‘ — اور نہ انہیں روک رکھنے (سے) کہ تم نے جو انہیں دیا ہے اس میں سے کچھ لے لو — سوائے اس کے کہ وہ کھلی بے حیائی کا ارتکاب کریں — یعنی مہر واپس لینے کے لیے تنگ نہ کرو۔
۴۔ ’’وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ‘‘ — اور ان کے ساتھ معروف طریقے سے زندگی گزارو — یعنی خوش اخلاقی اور انصاف سے۔
۵۔ ’’فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللّٰہُ فِيهِ خَيْرًا كَثِيرًا‘‘ — پھر اگر تم انہیں ناپسند کرو تو شاید کہ تم کسی چیز کو ناپسند کرو اور اللہ اس میں بہت زیادہ بھلائی رکھ دے — یعنی ناپسندیدگی صبر سے بہتر نتائج لاتی ہے۔
۶۔ عملی سبق: بیوی کے ساتھ ہمیشہ اچھے اخلاق سے پیش آؤ؛ تنگ نظری نہ کرو۔"""
),
513: (
"اور اگر تم ایک بیوی کے بدلے دوسری بیوی (لینے کا) ارادہ کرو — اور تم نے ان میں سے کسی کو ڈھیر سا مال دیا ہے — تو اس میں سے کچھ بھی مت لو — کیا تم اسے بہتان اور کھلے گناہ کے ساتھ لیتے ہو؟",
"""۱۔ ایک بیوی چھوڑ کر دوسری شادی — دیا ہوا مال واپس لینا حرام ہے۔
۲۔ ’’وَإِنْ أَرَدتُّمُ اسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَآتَيْتُمْ إِحْدَاهُنَّ قِنطَارًا فَلَا تَأْخُذُوا مِنْهُ شَيْئًا‘‘ — اور اگر تم ایک بیوی کے بدلے دوسری بیوی (لینے کا) ارادہ کرو — اور تم نے ان میں سے کسی کو ڈھیر سا مال دیا ہے — تو اس میں سے کچھ بھی مت لو — یعنی نئی بیوی کے لیے سابقہ بیوی کا مہر واپس نہ لو۔
۳۔ ’’أَتَأْخُذُونَهُ بُهْتَانًا وَإِثْمًا مُّبِينًا‘‘ — کیا تم اسے بہتان اور کھلے گناہ کے ساتھ لیتے ہو؟
۴۔ عملی سبق: جو مہر تم نے دیا ہے وہ عورت کا حق ہے؛ واپس لینا گناہ ہے۔"""
),
}
